import{_ as o,o as u,c as q,ag as r}from"./chunks/framework.CukOUUOK.js";const l=JSON.parse('{"title":"假话是地基，真话是炸药——从\\"双层生活\\"到报纸的诞生","description":"一、一个跨越文明的幽灵 人类文明史上有一个几乎无处不在的怪现象：一个社会越是高举道德旗帜，其私底下的行为就越是触目惊心。这不是某一个文明的特产，而是贯穿中西、横跨千年的结构性顽疾。 中国明清两代，\\"存…","frontmatter":{"title":"假话是地基，真话是炸药——从\\"双层生活\\"到报纸的诞生","categories":"信息与认知","tags":["信息管控","伦理","历史"],"description":"一、一个跨越文明的幽灵 人类文明史上有一个几乎无处不在的怪现象：一个社会越是高举道德旗帜，其私底下的行为就越是触目惊心。这不是某一个文明的特产，而是贯穿中西、横跨千年的结构性顽疾。 中国明清两代，\\"存…","date":"2026-08-31T12:00:00.000Z"},"headers":[],"relativePath":"posts/2026-08-31-lies-as-foundation.md","filePath":"posts/2026-08-31-lies-as-foundation.md","lastUpdated":1789992797000}'),n={name:"posts/2026-08-31-lies-as-foundation.md"};function s(p,t,a,e,g,i){return u(),q("div",null,[...t[0]||(t[0]=[r('<h1 id="假话是地基-真话是炸药——从-双层生活-到报纸的诞生" tabindex="-1">假话是地基，真话是炸药——从&quot;双层生活&quot;到报纸的诞生 <a class="header-anchor" href="#假话是地基-真话是炸药——从-双层生活-到报纸的诞生" aria-label="Permalink to &quot;假话是地基，真话是炸药——从&quot;双层生活&quot;到报纸的诞生&quot;">​</a></h1><h3 id="一、一个跨越文明的幽灵" tabindex="-1">一、一个跨越文明的幽灵 <a class="header-anchor" href="#一、一个跨越文明的幽灵" aria-label="Permalink to &quot;一、一个跨越文明的幽灵&quot;">​</a></h3><p>人类文明史上有一个几乎无处不在的怪现象：一个社会越是高举道德旗帜，其私底下的行为就越是触目惊心。这不是某一个文明的特产，而是贯穿中西、横跨千年的结构性顽疾。</p><p>中国明清两代，&quot;存天理、灭人欲&quot;被奉为国教，科举以四书五经为标准答案，贞节牌坊遍布乡野，&quot;饿死事小，失节事大&quot;写进了每一本女训女诫。但恰恰是在礼教最严苛的时代，社会却呈现出最极端的纵欲景观——《金瓶梅》以男性纵欲为标本，《痴婆子传》以女性纵欲为镜像，春宫画册广为流传，房中术被当作养生秘典。学者吴存存在《明清社会性爱风气》中一针见血地指出：<strong>&quot;明清两代也许可以说是中国历史上性爱观念最为混乱的时期，禁欲与纵欲的并行使这个时期的性爱观呈现出极其复杂的状态。&quot;</strong></p><p>欧洲的情况如出一辙。中世纪天主教会将禁欲推至极端——婚姻中的性行为只允许以生育为目的，一年中大量宗教节日禁止行房，修士修女必须独身。然而到了文艺复兴时期，教皇亚历山大六世公开豢养情妇、私生子众多，主教们大量不住教区、过着贵族般的奢靡生活，普通神父普遍蓄妾姘居，修道院沦为贵族寻欢的场所。薄伽丘《十日谈》中那些修士修女的荒唐故事，在当时根本不是什么文学夸张，而是社会的公开秘密。</p><p>这种&quot;说一套做一套&quot;的现象如此普遍、如此持久，以至于我们不得不追问：<strong>这到底是古人&quot;虚伪&quot;，还是某种更深层的结构性力量在驱动？</strong></p><h3 id="二、道德从来不是用来-信-的-是用来-用-的" tabindex="-1">二、道德从来不是用来&quot;信&quot;的，是用来&quot;用&quot;的 <a class="header-anchor" href="#二、道德从来不是用来-信-的-是用来-用-的" aria-label="Permalink to &quot;二、道德从来不是用来&quot;信&quot;的，是用来&quot;用&quot;的&quot;">​</a></h3><p>要理解这种分裂，首先必须打破一个现代人的思维惯性：我们以为古人宣传&quot;仁义礼智信&quot;，是因为他们真的相信这套东西。但绝大多数情况下，<strong>他们不是信徒，他们是使用者。</strong></p><p>&quot;存天理、灭人欲&quot;这六个字，朱熹说出来的时候，它是一套哲学命题，讨论的是宇宙本体和人性修养的关系。但到了明清，这套话被科举制度绑架之后，它变成了一个<strong>筛选机制</strong>——你不是真的需要做到&quot;灭人欲&quot;，你只需要在文章里写得像那么回事就行。考官看的是你的八股文写得规不规范，不是看你晚上回家干了什么。</p><p>这就产生了一个极其关键的效果：<strong>道德变成了一种&quot;准入资格&quot;，而不是一种&quot;生活标准&quot;。</strong> 就像今天考驾照不需要你真的会修车一样，古代读书人考科举不需要你真的&quot;灭人欲&quot;，他只需要在考卷上把&quot;天理人欲&quot;的辩证关系写得漂亮就行。一旦考上了、当了官、有了权，这套道德话语就变成了他用来<strong>约束别人的工具</strong>，而不是约束自己的。</p><p>所以你会发现一个规律：<strong>越是高喊道德的人，私下越放纵。</strong> 海瑞是极少数例外，正因为他是例外，才被树为楷模——如果大家都做得到，何至于需要树典型？</p><h3 id="三、-双层生活-不是系统故障-而是系统设计" tabindex="-1">三、&quot;双层生活&quot;不是系统故障，而是系统设计 <a class="header-anchor" href="#三、-双层生活-不是系统故障-而是系统设计" aria-label="Permalink to &quot;三、&quot;双层生活&quot;不是系统故障，而是系统设计&quot;">​</a></h3><p>&quot;说一套做一套&quot;不是这套系统出了bug，<strong>它本身就是这么设计的。</strong></p><p>以古代中国为例，这套&quot;双层生活&quot;被制度化得极其彻底：公共系统——科举考四书五经、朝廷表彰贞节牌坊、乡约宣讲圣谕——管的是&quot;秩序&quot;，确保社会分层稳定、底层安分守己；私人系统——士大夫纳妾狎妓、贵族蓄养伶人、富商买春——管的是&quot;欲望&quot;，为有权有势的人提供释放空间。这两套系统<strong>从来不要求彼此一致</strong>。事实上，它们之所以能稳定运行几百年，恰恰是因为它们<strong>互不干涉</strong>。你白天在衙门里判&quot;淫妇浸猪笼&quot;的案子，晚上回家搂着三房小妾喝酒——这在当时没有任何心理障碍，因为在当事人的认知框架里，<strong>这两件事分属完全不同的世界。</strong></p><p>支撑这种&quot;双层生活&quot;的，是三重结构性条件的叠加。</p><p><strong>第一重：权力不受制约。</strong> 明清的贞节观从来都是单向的——对女性要求从一而终、守节至死，对男性却从未提出对等的&quot;守身&quot;要求，一妻多妾是制度明文许可的。通房丫头、纳妾、狎妓，这些在制度上就是被允许的。所以与其说男人们在&quot;违背&quot;礼教，不如说礼教本来就只约束一半人。当规则只约束弱者、不约束强者时，规则就变成了笑话。</p><p><strong>第二重：信息高度不透明。</strong> 古代没有报纸、没有互联网、没有舆论监督。大户人家关起门来干什么，外人根本不知道。就算有人隐约听说，也没有渠道去核实、去曝光、去追究。&quot;家丑不可外扬&quot;不是一句空话，它是那个时代信息环境的真实写照。</p><p><strong>第三重：批判工具不存在。</strong> 我们今天有&quot;虚伪&quot;&quot;双标&quot;&quot;hypocrisy&quot;这些概念，我们可以指着一个人说&quot;你言行不一&quot;。但古代没有这套话语。在儒家的框架里，&quot;君君臣臣父父子子&quot;是天经地义的秩序，你质疑这个秩序，就是&quot;大逆不道&quot;。在基督教的框架里，质疑教会的权威就是&quot;异端&quot;，是要被烧死的。<strong>当一套系统不允许你从外部去审视它时，身处其中的人就永远看不见它的荒谬。</strong></p><h3 id="四、权力的-法外空间-从郭举人到嘉靖皇帝" tabindex="-1">四、权力的&quot;法外空间&quot;：从郭举人到嘉靖皇帝 <a class="header-anchor" href="#四、权力的-法外空间-从郭举人到嘉靖皇帝" aria-label="Permalink to &quot;四、权力的&quot;法外空间&quot;：从郭举人到嘉靖皇帝&quot;">​</a></h3><p>权力越大，&quot;玩法&quot;越没有底线——这几乎是一条铁律。</p><p>《白鹿原》里写郭举人买16岁少女田小娥做&quot;泡枣的药炉&quot;，很多人以为是陈忠实瞎编的。但&quot;阴枣&quot;（又称&quot;牝甘&quot;&quot;牝鸡&quot;）是陕西民间流传了上千年的习俗，前秦时期的《拾遗记》中就有西王母以&quot;岐山阴枣&quot;款待周穆王的记载，直到清代仍有文献提及类似情节。陈忠实自己说过，他小时候在农村就听说过这种习俗，写《白鹿原》时查阅了大量史料和地方志，才把这个细节写进去。田小娥唯一的反抗方式，是把枣从体内取出来扔进尿盆里泡，让郭举人吃的是尿泡的枣——这不是文学夸张，这是当时社会底层的真实处境。</p><p>苏童在《妻妾成群》中描写的陈佐千，把四房姨太太纳入一套精密的规训系统——老爷在哪房过夜，哪房就点红灯笼、享受&quot;捶脚&quot;的殊荣，第二天还有权点菜。看似是恩宠，本质上是把女性物化为一套可以量化的竞争机制。三太太梅珊因私通被秘密处死，投入后院古井；四太太颂莲精神崩溃发疯；丫鬟雁儿因私自点灯被罚跪雪地致死。这部小说被张艺谋改编为电影《大红灯笼高高挂》，获第48届威尼斯国际电影节银狮奖，并获第64届奥斯卡最佳外语片提名。</p><p>而帝王层面的放纵，更是登峰造极。汉灵帝下令后宫嫔妃宫女一律穿开裆裤，建千间&quot;裸游馆&quot;让14到18岁宫女裸体嬉戏，他昼夜饮酒观赏；还在后宫设&quot;宫中市&quot;，让宫女扮商贩，他扮商人调戏奸淫取乐。明武宗朱厚照在紫禁城西北建&quot;豹房&quot;，24小时纵欲，里面藏着美女、娈童、乐妓、少数民族女子，微服上街见妇女就抢。明世宗嘉靖皇帝沉迷方士陶仲文的媚药&quot;天丹铅&quot;，服药后&quot;不论白天夜间立即进入兴奋状态&quot;，一天临幸多达数十人，宫禁御幸的宫规彻底大乱，谢恩封赏都顾不上了。清代大学士纪晓岚，据野史笔记记载&quot;日御数女&quot;，五鼓一次、归寓一次、午间一次、薄暮一次、临卧一次，几天不近女色就&quot;肤欲裂，筋欲抽&quot;，乾隆见他两眼暴赤、颧红如火，问明原因后大笑，直接赐宫女二名伴宿。</p><p>这些不是孤例，而是<strong>权力不受约束时的常态</strong>。郭举人可以买16岁少女泡枣，因为他是举人、是地主、有钱有势；陈佐千可以把四房姨太太当玩物，因为他是家主、掌握着所有人的生杀予夺；嘉靖皇帝可以荒唐到二十几年不上朝，因为他是天子、没人敢管。</p><h3 id="五、-压抑-反弹-的人性铁律" tabindex="-1">五、&quot;压抑-反弹&quot;的人性铁律 <a class="header-anchor" href="#五、-压抑-反弹-的人性铁律" aria-label="Permalink to &quot;五、&quot;压抑-反弹&quot;的人性铁律&quot;">​</a></h3><p>但仅仅用权力结构来解释还不够。人性本身有一个铁律：<strong>你压得越狠，反弹越猛。</strong></p><p>学者在分析明清性爱风气时指出，&quot;禁欲与纵欲恰是人性中的两个极端，&#39;物极必反&#39;，压抑太甚，必定释放也剧。&quot;程朱理学把人的天然欲望定义为&quot;肮脏、不正当、有罪&quot;，要求&quot;存天理、灭人欲&quot;，这种极端压抑的结果，不是欲望消失了，而是欲望被驱赶到了地下，以更加扭曲、更加极端的形式爆发出来。</p><p>晚明的纵欲风气就是这种反弹的典型。冯梦龙、唐寅等人对理学提出批判，士大夫纷纷走向另一个极端——崇尚风流放诞、惊世骇俗。春宫画册广为流传，药石秘术（房中术）流行，甚至嘉靖皇帝本人都痴迷于此。色情文学泛滥，《金瓶梅》以男性纵欲为代表，《痴婆子传》以女性纵欲为代表，都在这个时期涌现。</p><p>欧洲也遵循同样的规律。中世纪教会的极端禁欲主义把一切世俗欲望定义为&quot;原罪&quot;，结果贵族的精神世界长期处于分裂状态——&quot;享乐&quot;与&quot;罪感&quot;在他们内心持续博弈，形成了一种无法化解的张力。这种张力累积到一定程度，便需要寻找出口。到文艺复兴前后，这种宗教化的肉体惩罚逐渐去神学化，演化为纯粹的感官游戏。</p><p>而基督教的&quot;罪感机制&quot;不但没有阻止放纵，反而为放纵提供了心理出口——一个贵族夜里干了荒唐事，第二天去教堂忏悔，神父说&quot;孩子，上帝宽恕你&quot;，于是他心安理得地走出教堂，晚上继续干同样的事。忏悔变成了一种&quot;<strong>赎罪券</strong>&quot;——我犯了罪，但我忏悔了，所以我&quot;干净&quot;了，可以重新开始了。这种机制让放纵变成了一种<strong>可循环的行为</strong>：犯罪→忏悔→赦免→再犯罪→再忏悔……无穷无尽。</p><h3 id="六、说真话的人-李贽与金圣叹" tabindex="-1">六、说真话的人：李贽与金圣叹 <a class="header-anchor" href="#六、说真话的人-李贽与金圣叹" aria-label="Permalink to &quot;六、说真话的人：李贽与金圣叹&quot;">​</a></h3><p>在&quot;全社会都看见了但没人说&quot;的格局中，偏偏有人站出来说了。他们一个被关进监狱后自己割喉而死，一个被推上刑场砍了头——但他们死前说的话，到今天听着还烫嘴。</p><p><strong>李贽（1527—1602）</strong> 是晚明最&quot;危险&quot;的思想家，没有之一。他的核心武器叫&quot;童心说&quot;——&quot;夫童心者，绝假纯真，最初一念之本心也。若失却童心，便失却真心；失却真心，便失却真人。&quot;翻译成大白话就是：<strong>人一旦开始&quot;装&quot;，就不是人了。</strong></p><p>然后他把矛头直接对准了儒学的根基——六经、《论语》、《孟子》。他说了一句在当时堪称&quot;核弹级&quot;的话：<strong>&quot;六经、《语》、《孟》，乃道学之口实，假人之渊薮也。&quot;</strong> 你们天天拜的那些经典，不过是假道学家们用来骗人的工具，是伪君子的老巢。</p><p>他进一步指出，整个社会的虚伪就是从读书开始的——小时候耳朵听着&quot;道理&quot;进去，童心就丢了一层；长大后&quot;闻见道理&quot;越积越多，童心就彻底没了。所以满天下都是&quot;假人&quot;：</p><blockquote><p>&quot;盖其人既假，则无所不假矣。由是而以假言与假人言，则假人喜；以假事与假人道，则假人喜；以假文与假人谈，则假人喜。无所不假，则无所不喜。&quot;</p></blockquote><p>这段话放到今天读，是不是觉得他在说当下某些事？——<strong>假人说假话，假人听假话，假人办假事，假人写假文章。全社会都假，全社会都高兴。</strong></p><p>李贽最狠的一刀，是直接砍向了&quot;存天理、灭人欲&quot;这六个字。他说：<strong>&quot;穿衣吃饭，即是人伦物理；除却穿衣吃饭，无伦物矣。&quot;</strong> 人活着要吃饭穿衣，这就是最大的&quot;天理&quot;。除此之外，没有什么悬在头顶的抽象道德。这话等于直接宣布：程朱理学那套&quot;天理&quot;是扯淡。他还公开给&quot;私欲&quot;正名：<strong>&quot;私者，人之心也，人必有私而后其心乃见。&quot;</strong> ——人有私心才是正常的，没有私心的人才可怕。</p><p>万历三十年（1602年），礼科给事中张问达上疏弹劾李贽，罪名是&quot;<strong>敢倡乱道，惑世诬民</strong>&quot;。万历皇帝下旨：逮捕，烧书，一本不留。值得注意的是，弹劾他的张问达是东林党人——也就是我们通常认为的&quot;改革派&quot;&quot;正人君子&quot;。这说明在&quot;维护儒家纲常&quot;这件事上，&quot;改革派&quot;和&quot;保守派&quot;是一致的——谁敢动儒学的根基，谁就是敌人，不管你是左是右。</p><p>李贽被捕时已经75岁，被关进北京通州的大牢。他拒绝屈服，也拒绝被押回福建老家——他说了一句让人心碎的话：<strong>&quot;我年七十有六，死以归为？&quot;</strong> 万历三十年三月十五日，他趁剃头时夺过剃刀，割断自己的喉咙，次日身亡。朝廷下令焚毁他的一切著作，&quot;已刻未刻者，令所在官司尽行烧毁&quot;。但烧得掉吗？他的书早就&quot;人挟一册，以为奇货&quot;，流传到日本、朝鲜，直到今天还在被阅读。</p><p><strong>金圣叹（1608—1661）</strong> 走的是另一条路——用&quot;嬉笑怒骂&quot;来解构一切权威。他做的第一件&quot;大逆不道&quot;的事，是把《水浒传》和《西厢记》抬到了跟《离骚》《史记》一样高的地位，合称&quot;六才子书&quot;。在正统文人眼里，《水浒传》是&quot;诲盗之书&quot;，《西厢记》是&quot;淫书&quot;——把它们跟《离骚》并列，等于指着所有道学先生的鼻子说：<strong>你们看不起的东西，比你们读的那堆破书强一万倍。</strong></p><p>他对《西厢记》的评价更是石破天惊：<strong>&quot;《西厢记》断断不是淫书！断断是妙文！&quot;</strong> 他说张生和崔莺莺的爱情写的是&quot;必至之情&quot;，跟《诗经·国风》没有本质区别。他最毒的一刀，砍在了宋江身上——传统评《水浒》都说宋江&quot;忠义两全&quot;，金圣叹偏不。他说宋江的&quot;忠义&quot;是假的，是&quot;假道学、真强盗&quot;——口口声声&quot;替天行道&quot;，实际上只想招安做官，用兄弟们的血换自己的前程。</p><p>他还公开嘲笑科举。考题是&quot;孟子将见王&quot;，他在试卷四角各写一个&quot;吁&quot;字。考官问什么意思，他说：&quot;王上朝的时候，旁边四个内侍不是要喊&#39;吁&#39;吗？这不就完了？&quot;——直接把&quot;孟子见王&quot;这件神圣的事变成了一个笑话。</p><p>顺治十八年（1661年），苏州吴县知县任维初横征暴敛、盗卖官粮，激起民愤。金圣叹和一群秀才到文庙&quot;哭庙&quot;，控告贪官。这本来是苏州的老传统——明朝时秀才们这么干，官府多半会认怂。但清兵入关才十几年，清廷对江南文人的任何集体行动都高度敏感。结果，金圣叹被定为&quot;首犯&quot;，罪名是&quot;摇动人心倡乱&quot;，与另外十七人一同被判斩立决。</p><p>据《辛丑纪闻》记载，行刑时&quot;炮声一震，一百二十一人皆毙死&quot;——不仅十八个主犯，还有大量被牵连的人一同被杀。</p><h3 id="七、他们为什么必须死" tabindex="-1">七、他们为什么必须死？ <a class="header-anchor" href="#七、他们为什么必须死" aria-label="Permalink to &quot;七、他们为什么必须死？&quot;">​</a></h3><p>他们到底触动了什么，让统治者非杀不可？</p><p>表面上看，李贽是&quot;倡乱道&quot;，金圣叹是&quot;抗粮谋反&quot;。但你仔细想想——李贽写过一句煽动暴力的话吗？没有。金圣叹组织过武装反抗吗？没有。他们做的事情，说到底就是<strong>说了真话</strong>。</p><p>但&quot;说真话&quot;恰恰是最致命的。因为一个建立在&quot;假&quot;之上的系统，最怕的就是有人说&quot;这是假的&quot;。</p><p>李贽说&quot;六经是假人之渊薮&quot;——这等于告诉天下读书人：你们读的那套东西是骗人的，你们的人生追求是虚的，你们用道德换功名的整套逻辑是肮脏的。这不是学术争论，这是<strong>釜底抽薪</strong>。</p><p>金圣叹说&quot;宋江的忠义是假的&quot;——这等于在告诉所有人：那些嘴上喊着&quot;忠君爱国&quot;的官员，跟宋江一样，都是&quot;假忠义、真权诈&quot;的小人。这不是文学评论，这是<strong>政治暗杀</strong>——用笔杀掉了整个官僚体系的合法性叙事。</p><p>他们被镇压的原因不是&quot;说了什么具体的话&quot;，而是<strong>他们证明了整个系统的底层逻辑是假的</strong>。一旦这个认知扩散开来，科举没人信了、礼教没人守了、忠义没人敬了——整个统治秩序就会崩塌。</p><p><strong>杀李贽，不是因为他的书有多危险，而是因为他的书会让人&quot;醒过来&quot;。</strong><br><strong>杀金圣叹，不是因为他犯了什么罪，而是因为他让所有人看见了&quot;皇帝没穿衣服&quot;。</strong></p><p>这就是为什么，一个社会越是需要&quot;统一思想&quot;，就越容不下说真话的人。不是因为真话有害，而是因为<strong>假话是地基，真话是炸药</strong>。</p><h3 id="八、从-没人说-到-有人说了-报纸的诞生" tabindex="-1">八、从&quot;没人说&quot;到&quot;有人说了&quot;：报纸的诞生 <a class="header-anchor" href="#八、从-没人说-到-有人说了-报纸的诞生" aria-label="Permalink to &quot;八、从&quot;没人说&quot;到&quot;有人说了&quot;：报纸的诞生&quot;">​</a></h3><p>那么，从&quot;大家都这么干但没人说&quot;到&quot;有人开始说了&quot;，中间到底发生了什么？答案的核心就是两个字：<strong>报纸</strong>。</p><p>但报纸不是谁&quot;发明&quot;的，它是被五股力量同时&quot;逼&quot;出来的。</p><p><strong>第一股力量：全球贸易。</strong> 15—16世纪地理大发现之后，欧洲的商业从地中海扩展到了全球。商人需要知道：船什么时候到？香料什么价？西班牙舰队在哪？这些信息靠以前那种口口相传、手抄新闻信根本不够用了。1566年，威尼斯出现了定期手抄新闻——但威尼斯的贸易很快衰落，真正接过接力棒的是北欧。</p><p><strong>第二股力量：印刷术。</strong> 1450年前后，古登堡在美因茨发明了金属活字印刷术。这项技术本来是为大量印刷《圣经》服务的，但很快被用到了新闻上——它能批量复制，成本远低于手抄，信息传播的速度和规模一下子上了几个数量级。</p><p><strong>第三股力量：民族语言的标准化。</strong> 文艺复兴之后，意大利语、法语、德语、英语各自形成了标准书面形式。没有这个条件，报纸写出来谁看得懂？</p><p><strong>第四股力量：统一国家的形成。</strong> 中世纪欧洲封建割据，关卡林立，信息流通极其困难。15—16世纪，法国、英国等国逐步加强王权、削减诸侯势力，国内贸易壁垒减少，信息流通的通道才打通了。</p><p><strong>第五股力量：读者群的出现。</strong> 文艺复兴把文化从僧侣阶层的垄断下解放出来，转向世俗社会。商人、市民、贵族都开始识字了，有人看了，报纸才能活。</p><p>这五个条件缺一不可。少了任何一个，报纸都出不来。1605年前后，德国斯特拉斯堡出现了最早的印刷报纸；1609年，德国《通告—报道或新闻报》和《德国观察周刊》成为最早定期出版的印刷周刊；1660年，德国出现了最早的日报《莱比锡新闻》；1702年，英国的《每日新闻》初步具备现代日报的形态。</p><h3 id="九、报纸为什么能打破-双层生活" tabindex="-1">九、报纸为什么能打破&quot;双层生活&quot;？ <a class="header-anchor" href="#九、报纸为什么能打破-双层生活" aria-label="Permalink to &quot;九、报纸为什么能打破&quot;双层生活&quot;？&quot;">​</a></h3><p>报纸的本质是什么？<strong>它让&quot;私底下的事&quot;变成了&quot;公共的事&quot;。</strong></p><p>在没有报纸的时代，郭举人在家泡枣、嘉靖皇帝在豹房纵欲，这些事只有当事人和身边几个人知道。信息被封锁在私人空间里，没有传播渠道，就没有公共讨论，就没有舆论压力，就没有改变的可能。</p><p>报纸出现之后，游戏规则变了：</p><p>它创造了一个&quot;公共空间&quot;。以前，公共空间只有两个——朝廷和教堂。朝廷说什么是&quot;天理&quot;，教堂说什么是&quot;上帝旨意&quot;，没有第三个声音。报纸创造了第三个空间：一个不属于朝廷、不属于教堂、由普通市民阅读和讨论的空间。</p><p>它让&quot;私事&quot;变成了&quot;公事&quot;。一个官员贪了多少钱、一个贵族干了什么荒唐事，一旦被报纸登出来，就不再是&quot;家丑&quot;，而是公共事件。这就是为什么报纸从诞生之日起就被权力视为威胁。</p><p>它提供了&quot;批判的武器&quot;。以前，李贽说&quot;六经是假人之渊薮&quot;，只能写在书里，流传范围极其有限，而且随时可能被禁毁。但报纸是定期出版的，它持续不断地向公众输出信息、观点和批判，形成一种<strong>累积性的舆论压力</strong>，这是任何一本书都做不到的。</p><h3 id="十、启蒙运动-报纸的思想加速器" tabindex="-1">十、启蒙运动：报纸的思想加速器 <a class="header-anchor" href="#十、启蒙运动-报纸的思想加速器" aria-label="Permalink to &quot;十、启蒙运动：报纸的思想加速器&quot;">​</a></h3><p>报纸提供了&quot;硬件&quot;，启蒙运动提供了&quot;软件&quot;。</p><p>18世纪，伏尔泰、孟德斯鸠、卢梭等人写的东西，其实并不像我们今天想象的那样&quot;一出版就轰动&quot;。事实上，他们中的大多数人都在跟审查制度做斗争——孟德斯鸠的《波斯人信札》在法国是禁书，他不得不使用化名、在国外出版；伏尔泰的《哲学通信》被法国最高法院下令焚毁，出版商被投入巴士底狱，伏尔泰本人不得不逃出国境。</p><p>但关键在于：<strong>禁了也没用。</strong> 因为报纸、小册子、地下印刷网络已经形成了一套完整的信息传播体系。法国大革命前，启蒙书籍虽然在&quot;合法渠道&quot;上被压制，但在地下市场广为流传。咖啡馆里有人朗读报纸，沙龙里有人讨论小册子，书商偷偷印刷盗版——整个社会的信息流通已经不可能被完全封锁了。</p><p>1789年，法国《人权宣言》第11条明确规定：&quot;自由传达思想和意见是人类最宝贵的权利之一。因此，每个公民都有言论、著述和出版的自由。&quot;这是人类历史上<strong>第一次以法律形式确认新闻自由</strong>。</p><p>但这个过程绝不是一帆风顺的。拿破仑上台后查封了所有反对派报纸，留下名言&quot;一张报纸可抵三千毛瑟枪&quot;。复辟的波旁王朝也反复恢复和取消新闻检查。法国新闻自由的确立，直到1881年《新闻自由法》颁布才算真正完成——从1789年到1881年，整整将近一百年。</p><h3 id="十一、中国-从-邸报-到-申报" tabindex="-1">十一、中国：从&quot;邸报&quot;到&quot;申报&quot; <a class="header-anchor" href="#十一、中国-从-邸报-到-申报" aria-label="Permalink to &quot;十一、中国：从&quot;邸报&quot;到&quot;申报&quot;&quot;">​</a></h3><p>中国的情况更复杂。中国古代有&quot;邸报&quot;——唐代的《开元杂报》、宋代的《邸报》、清代的《京报》，但这些都不是现代意义上的报纸。它们是<strong>官方的内部通报</strong>，只登皇帝的谕旨、大臣的奏章、官员的升降，不登新闻、不发表评论、不允许批评。本质上是统治系统内部的&quot;文件传阅&quot;，跟老百姓没有任何关系。</p><p>中国近代报刊的诞生，完全是外力推动的。1815年，英国传教士米怜在马六甲创办了《<strong>察世俗每月统记传</strong>》——这是中国近代第一份中文报刊。它的目的很明确：传教。为了减少阻力，它大量附会儒学，每期封面上印一句孔子语录，用&quot;孔孟加耶稣&quot;的模式来包装基督教义。1822年，葡萄牙人在澳门创办了《<strong>蜜蜂华报</strong>》——这是中国境内第一份近代报纸，但它用葡文出版，读者仅限澳门的葡萄牙人社群。1872年，英国商人美查在上海创办了《<strong>申报</strong>》——这是近代中国影响最大、发行时间最长的中文报纸，一直出版到1949年，历时77年。《申报》从创刊之日起就强调自己是&quot;新闻纸&quot;，主张&quot;记录一切&quot;——&quot;凡国家之政治，风俗之变迁，中外交涉之要务，商贾贸易之利弊，与夫一切可惊可愕可喜可叹之事，足以新人听闻者，靡不毕载&quot;。</p><p>但真正让报纸在中国发挥&quot;打破双层生活&quot;作用的，是1895年甲午战败之后的<strong>维新变法运动</strong>。</p><p>短短三年间（1895—1898），中国的报纸从19家猛增到70家。其中最著名的两份：梁启超主编的《时务报》（1896年，上海），发行量创纪录，梁启超以&quot;时务体&quot;政论猛烈抨击旧制度，鼓吹变法；严复主编的《国闻报》（1897年，天津），严复在报上连续发表文章，指出中国若想富强，&quot;其本，则亦于民智、民力、民德三者加之意而已&quot;——启蒙才是根本。这两份报纸一南一北，彼此呼应，形成了中国近代第一波全国性的舆论浪潮。</p><p>更有意思的是，这些报纸之所以能存活，很大程度上得益于<strong>上海租界</strong>的特殊地位。租界是&quot;国中之国&quot;，清政府的行政权力在这里被阻隔。报人利用外商名义在领事馆注册，挂&quot;洋旗&quot;出版，清廷鞭长莫及。正如时人所说：&quot;则以托足租界之故，始得免婴国内政治上之暴力。&quot;1903年的&quot;<strong>苏报案</strong>&quot;是一个标志性事件——上海《苏报》刊登章士钊等人鼓吹革命的文章，清廷要求租界工部局交人，但租界拒绝无条件移交，最终在会审公廨进行审判。这个案件本身就说明：报纸已经创造了一个权力无法完全控制的公共空间。</p><h3 id="十二、假话是地基-真话是炸药" tabindex="-1">十二、假话是地基，真话是炸药 <a class="header-anchor" href="#十二、假话是地基-真话是炸药" aria-label="Permalink to &quot;十二、假话是地基，真话是炸药&quot;">​</a></h3><p>从&quot;大家都这么干但没人说&quot;到&quot;有人开始说了&quot;，中间发生了什么？</p><p>答案是：<strong>信息流通的渠道被打通了。</strong></p><p>在没有报纸的时代，权力可以轻松地维持&quot;双层生活&quot;，因为信息被封锁在私人空间里，没有传播渠道。但报纸出现之后，它做了三件根本性的事：它把&quot;私事&quot;变成了&quot;公事&quot;——一个人关起门来干什么，一旦被报纸曝光，就变成了公共事件，就要面对舆论的审视；它创造了一个独立于权力的&quot;公共空间&quot;——在这个空间里，人们可以讨论、质疑、批评，而这些事情以前是不可能发生的；它让&quot;批判&quot;变成了一种可持续的行为——一本书可能被禁毁，一个思想家可能被杀掉，但报纸是定期出版的，它每天都在输出，每天都在积累，形成一种权力无法完全消灭的舆论力量。</p><p>这就是为什么拿破仑说&quot;一张报纸可抵三千毛瑟枪&quot;——因为他知道，<strong>枪只能杀一个人，但报纸能唤醒一百万人。</strong></p><p>中国和欧洲的路径不同——欧洲是从商业需求出发，自下而上地长出了报纸；中国是被西方列强打醒之后，由传教士引入、由维新派接棒，自上而下地用报纸来&quot;开启民智&quot;。但最终的效果是一样的：<strong>一旦信息开始流通，&quot;双层生活&quot;就再也维持不下去了。</strong></p><h3 id="尾声-一个永恒的警示" tabindex="-1">尾声：一个永恒的警示 <a class="header-anchor" href="#尾声-一个永恒的警示" aria-label="Permalink to &quot;尾声：一个永恒的警示&quot;">​</a></h3><p>最后需要指出的是，这种&quot;宣传的&quot;和&quot;实际做的&quot;之间的裂缝，<strong>不是古人的专利，而是人类社会的一种结构性特征</strong>。</p><p>任何道德体系，当它被制度化、被权力裹挟之后，都会产生类似的效应——它创造的不是道德的人，而是善于表演道德的人。区别只在于：在现代社会，这套&quot;双层生活&quot;被法治、舆论监督和个人权利意识部分地消解了；而在古代，由于权力高度集中、信息高度不透明、底层完全缺乏话语权，这种分裂被放大到了极致。</p><p>所以，与其说古人&quot;虚伪&quot;，不如说他们生活在一个<strong>道德被工具化、欲望被地下化、权力不受约束</strong>的结构性困境中。《金瓶梅》的伟大之处，正在于它没有站在道德高地上审判任何人，而是冷静地呈现了这个困境中每一个真实的人——包括他们的欲望、他们的挣扎、他们的堕落和他们的无奈。</p><p>而李贽和金圣叹的伟大之处，在于他们用生命证明了一件事：<strong>假话是地基，真话是炸药。一个不允许被质疑的系统，怎么可能不虚伪？</strong></p><p>真正该问的问题从来不是&quot;古人为什么这么虚伪&quot;，而是——<strong>我们今天的系统，允许被质疑吗？</strong></p><hr><blockquote><p>本文同步自知乎，<a href="https://zhuanlan.zhihu.com/p/2077836161939158051" target="_blank" rel="noreferrer">查看原文</a>（3 赞）</p></blockquote>',96)])])}const d=o(n,[["render",s]]);export{l as __pageData,d as default};
